using System;using System.IO;using System.Drawing;using System.Linq;using System.Threading.Tasks;using System.Windows.Forms;
namespace CFEditor {
sealed partial class EditorForm {
 readonly AssetLibrary library=new AssetLibrary();int libraryIndex;readonly ActionButton[] libraryTabs=new ActionButton[4];Label libraryFile,libraryLevel,libraryHint;GlassNumber inputLevel,outputLevel,lowCut,highCut;CheckBox automatic,filterSwitch;ActionButton loadAsset,clearAsset,exportAssets;bool libraryUpdating;
 void BuildLibrary(){
  var p=Page();var card=StackCard(p,"BIBLIOTECA NAM + IR",355);var f=Flow(card);f.FlowDirection=FlowDirection.TopDown;f.WrapContents=false;
  var tabs=new FlowLayoutPanel{AutoSize=true,BackColor=Color.Transparent};f.Controls.Add(tabs);for(int i=0;i<4;i++){int n=i;var b=Button(i==3?"NAM":"IR"+(i+1),()=>{libraryIndex=n;ShowLibrary();},130);b.Height=30;libraryTabs[i]=b;tabs.Controls.Add(b);}
  var file=new FlowLayoutPanel{AutoSize=true,BackColor=Color.Transparent,WrapContents=false};f.Controls.Add(file);loadAsset=AsyncButton("Cargar IR…",LoadAsset,170,false);file.Controls.Add(loadAsset);libraryFile=LabelText("Selecciona un archivo",true);libraryFile.ForeColor=UITheme.Muted;libraryFile.MaximumSize=new Size(760,50);file.Controls.Add(libraryFile);clearAsset=Button("Vaciar",()=>{library.Slots[libraryIndex]=null;ShowLibrary();},110);file.Controls.Add(clearAsset);
  libraryHint=LabelText("WAV mono · 48 kHz · hasta 2048 muestras");f.Controls.Add(libraryHint);
  var levels=new FlowLayoutPanel{AutoSize=true,BackColor=Color.Transparent};f.Controls.Add(levels);automatic=new CheckBox{Text="Volumen automático",Checked=true,AutoSize=true,ForeColor=UITheme.Success,Font=UITheme.Bold,Margin=new Padding(8,12,20,8)};levels.Controls.Add(automatic);outputLevel=new GlassNumber{Minimum=-60,Maximum=12,DecimalPlaces=1,Increment=.1m,Width=100,Margin=new Padding(8)};levels.Controls.Add(outputLevel);levels.Controls.Add(LabelText("dB"));levels.Controls.Add(LabelText("Entrada NAM",true));inputLevel=new GlassNumber{Minimum=-36,Maximum=0,Value=(decimal)LibrarySlot.DefaultInputDb,Width=90,Margin=new Padding(8)};levels.Controls.Add(inputLevel);levels.Controls.Add(LabelText("dB"));libraryLevel=LabelText("",true);libraryLevel.ForeColor=UITheme.Success;f.Controls.Add(libraryLevel);
  var filters=new FlowLayoutPanel{AutoSize=true,BackColor=Color.Transparent};f.Controls.Add(filters);filterSwitch=new CheckBox{Text="Cortes automáticos",Checked=true,AutoSize=true,ForeColor=UITheme.Success,Font=UITheme.Bold,Margin=new Padding(8,12,20,8)};filters.Controls.Add(filterSwitch);filters.Controls.Add(LabelText("Low Cut",true));lowCut=new GlassNumber{Minimum=20,Maximum=2000,Value=80,Width=100,Margin=new Padding(8)};filters.Controls.Add(lowCut);filters.Controls.Add(LabelText("High Cut",true));highCut=new GlassNumber{Minimum=1000,Maximum=22000,Value=8000,Width=100,Margin=new Padding(8)};filters.Controls.Add(highCut);filters.Controls.Add(LabelText("Hz · 12 dB/oct"));
  var actions=new FlowLayoutPanel{AutoSize=true,BackColor=Color.Transparent,Padding=new Padding(0,4,0,0)};f.Controls.Add(actions);exportAssets=AsyncButton("Guardar paquete NAM + IR…",ExportAssets,270,false);actions.Controls.Add(exportAssets);var send=new ActionButton{Text="Transferir al ampli",Width=220,Enabled=false};actions.Controls.Add(send);f.Controls.Add(LabelText("Transferencia directa pendiente del receptor CF."));
  automatic.CheckedChanged+=delegate{UpdateLibrarySettings();};filterSwitch.CheckedChanged+=delegate{UpdateLibrarySettings();};inputLevel.ValueChanged+=delegate{UpdateLibrarySettings();};outputLevel.ValueChanged+=delegate{UpdateLibrarySettings();};lowCut.ValueChanged+=delegate{UpdateLibrarySettings();};highCut.ValueChanged+=delegate{UpdateLibrarySettings();};ShowLibrary();
 }
 async Task LoadAsset(){int slot=libraryIndex;using(var d=new OpenFileDialog{Filter=slot==3?"Neural Amp Modeler (*.nam)|*.nam":"Impulse Response WAV (*.wav)|*.wav"}){if(d.ShowDialog(this)!=DialogResult.OK)return;await Task.Run(()=>{if(slot==3)library.LoadNAM(d.FileName);else library.LoadIR(slot,d.FileName);});ShowLibrary();message.Text="✓ Archivo validado en la biblioteca. Todavía no se ha enviado al ampli.";message.ForeColor=UITheme.Success;}}
 void ShowLibrary(){if(libraryFile==null)return;libraryUpdating=true;try{var s=library.Slots[libraryIndex];for(int i=0;i<4;i++){libraryTabs[i].Text=(i==3?"NAM":"IR"+(i+1))+(library.Slots[i]!=null?" ✓":"");libraryTabs[i].Active=i==libraryIndex;libraryTabs[i].Invalidate();}bool nam=libraryIndex==3;loadAsset.Text=nam?"Cargar NAM…":"Cargar IR…";libraryFile.Text=s==null?"Selecciona un archivo":s.Name+"  ✓";libraryFile.ForeColor=s==null?UITheme.Muted:UITheme.Success;libraryHint.Text=nam?"A2 Lite · mono · 48 kHz · CHIME GROUP 1":"WAV mono · 48 kHz · hasta 2048 muestras";clearAsset.Enabled=s!=null;automatic.Enabled=s!=null;automatic.Checked=s==null||s.Automatic;inputLevel.Visible=nam;inputLevel.Enabled=nam&&s!=null;inputLevel.Value=s==null?(decimal)LibrarySlot.DefaultInputDb:(decimal)s.InputDb;outputLevel.Enabled=s!=null&&!s.Automatic;filterSwitch.Enabled=!nam&&s!=null;filterSwitch.Checked=s==null||s.Filters;lowCut.Enabled=highCut.Enabled=!nam&&s!=null&&s.Filters;lowCut.Value=s==null?80:(decimal)s.LowHz;highCut.Value=s==null?8000:(decimal)s.HighHz;if(s!=null){double db=s.EffectiveDb();outputLevel.Value=(decimal)Math.Max(-60,Math.Min(12,db));libraryLevel.Text=(nam?"Entrada: "+s.InputDb.ToString("0")+" dB · ":"")+(s.Automatic?"Salida automática: ":"Salida manual: ")+db.ToString("0.0")+" dB";}else{outputLevel.Value=0;libraryLevel.Text="";}exportAssets.Enabled=library.Slots.Any(v=>v!=null);}finally{libraryUpdating=false;}}
 void UpdateLibrarySettings(){if(libraryUpdating)return;var s=library.Slots[libraryIndex];if(s==null)return;s.Automatic=automatic.Checked;s.OutputDb=(double)outputLevel.Value;s.InputDb=(double)inputLevel.Value;s.Filters=filterSwitch.Checked;s.LowHz=(double)lowCut.Value;s.HighHz=(double)highCut.Value;try{IRFilters.Validate(s.LowHz,s.HighHz);ShowLibrary();}catch(Exception e){Error(e);}}
 async Task ExportAssets(){using(var d=new SaveFileDialog{Filter="Paquete Catalyst CF (*.cfxpack)|*.cfxpack",FileName="Catalyst-NAM-IR.cfxpack"}){if(d.ShowDialog(this)!=DialogResult.OK)return;byte[] bytes=await Task.Run(()=>library.Build());File.WriteAllBytes(d.FileName,bytes);AssetLibrary.Validate(File.ReadAllBytes(d.FileName));message.Text="✓ Paquete validado y guardado. No se ha instalado firmware ni enviado datos USB.";message.ForeColor=UITheme.Success;}}
}
}
